let programs = [p1,p2,p3,p4,p5,p6,p7];

let edge_length = 28;
let stroke_weight = 2;
let show_tree = true;
let show_tiles = true;
let reverse_order = true;
let randomize_order = false;
let squareframe = false;
let reverse_edge = false;
let current_prog_idx = 0;

let last_id = 1;
let g;
let count = 0;
let col = ["#3DB2FF","#FFB830","#FF2442","#FF7600","#185ADB","#0A1931","#99154E"];

let get_r = (n) => edge_length/(2*sin(PI/n));
let get_apothem = (n) => edge_length/(2*tan(PI/n));
let dist_ab = (a, b) => sqrt((a[0] - b[0])**2 + (a[1] - b[1])**2);

let main_prog = [];
let run = 1;
let done_p = 0;
let cycleTimer = 0;

function parse_program(s) {
	let lines = s.split('
');
	lines = lines.filter(line => line.length >= 4);
	lines = lines.filter(line => !line.match('//'));
	lines = lines.map((t) => t.replace('+=',',').replace(/[^0-9&,]/g,''));
	lines = lines.filter(line => line.length >= 1);
	lines = lines.map((t) => t.split(',').filter(t => t.length>=1).map((t) => int(t)));
	if(lines.length < 1 || lines[0].length != 2){return [];}
	return lines;
}

function initGridWithProg(idx) {
	current_prog_idx = idx % programs.length;
	main_prog = parse_program(programs[current_prog_idx]);
	last_id = 1;
	count = 0;
	done_p = 0;
	run = 1;
	g = new grid(width/2, height/2);
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	rectMode(CENTER);
	frameRate(30);
	initGridWithProg(0);
}

function draw() {
	let bass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof bass_ratio !== 'undefined' ? bass_ratio : 0);
	let perc = (typeof percussive !== 'undefined') ? percussive : 0;
	let is_beat_active = (typeof is_beat !== 'undefined' && is_beat) || perc > 0.6;

	background("#1a1a24");

	if (is_beat_active && cycleTimer > 90) {
		cycleTimer = 0;
		initGridWithProg(current_prog_idx + 1);
	}
	cycleTimer++;

	edge_length = map(bass, 0, 1, 24, 38);
	stroke_weight = map(perc, 0, 1, 1.5, 3.5);

	if (run == 1 && g) {
		for (let i = 0; i < 12; i += 1) {
			g.add_tile_to_front();
		}
		if (g.front.length === 0) {
			done_p = 1;
			if (cycleTimer > 60) {
				cycleTimer = 0;
				initGridWithProg(current_prog_idx + 1);
			}
		} else {
			count += 1;
		}
	}

	if (g) {
		push();
		g.draw_grid();
		pop();
	}
}

function constraints(a,b) {
	let h = min(width, height);
	if(!squareframe) return dist_ab([a,b], [width/2, height/2]) > 0.45 * h;
	let padding = 70;
	return (a < padding)||(b < padding)||(a > width - padding)||(b > height - padding);
}

function get_segments_from_points(s) {
	let out = [];
	let pr = s[0];
	for (let a = 1; a < s.length; a += 1) {
		out.push([pr, s[a]]);
		pr = s[a];
	}
	return out;
}

function polygonArr(radius, npoints, angZero) {
	let arr = [];
	let angle = TWO_PI / npoints;
	for (let a = angZero; a < TWO_PI + angZero + 0.00001; a += angle) {
		arr.push([cos(a) * radius, sin(a) * radius]);
	}
	return arr;
}

function segments_are_close_enough(a,b) {
	let e = 0.01;
	if(dist_ab(a[0], b[0])<e && dist_ab(a[1], b[1])<e)return true;
	if(dist_ab(a[1], b[0])<e && dist_ab(a[0], b[1])<e)return true;
	return false;
}

class grid {
	constructor(sx, sy) {
		this.sx = sx;
		this.sy = sy;
		if (!main_prog || main_prog.length === 0) {
			main_prog = [[0, 6], [0, 6, 1, 0, 4]];
		}
		this.start_c = new tile(0, main_prog[0][1], sx, sy, 0, 2*PI/(main_prog[0][1]*2));
		this.start_c.c = main_prog[0][0];
		this.s = [this.start_c];
		this.front = [this.start_c];
		this.done = 0;
	}

	f(col_t, sides_t, side_t, col_out, sides_out, new_tt, current_t){
		if(current_t < this.front.length &&
		   this.front[current_t].n_sides == sides_t &&
		   this.front[current_t].c == col_t &&
		   side_t == new_tt &&
		   this.done == 0 &&
		   this.front[current_t].adj[new_tt] == -1){

			let new_tile = this.front[current_t].get_new_tile(new_tt, sides_out);
			new_tile.c = col_out;

			if(!constraints(new_tile.x, new_tile.y)){
				this.front.push(new_tile);
				this.s.push(new_tile);
				update_tiles(new_tile, this.s);
				update_tiles(new_tile, this.front);
			}else{
				new_tile.out_of_bounds = 1;
				this.s.push(new_tile);
				update_tiles(new_tile, this.s);
			}

			this.done = 1;
		}
	}

	add_tile_to_front(){
		if (this.front.length == 0) return;

		let t = 0;
		if(reverse_order) t = this.front.length - 1;
		if(randomize_order) t = floor(random(this.front.length));

		let opport = [];
		for (let i = 0; i < this.front[t].adj.length; i += 1) {
			if(this.front[t].adj[i] == -1){
				opport.push(i);
			}
		}

		if(opport.length == 0){
			this.front.splice(t, 1);
			return;
		}
		let new_t = reverse_edge ? opport.sort()[opport.length-1] : opport.sort()[0];
		this.done = 0;
		for(let k = 1; k < main_prog.length; k+=1){
			this.f(...main_prog[k], new_t, t);
		}
		if (t < this.front.length) {
			this.front[t].adj[new_t] = -2;
		}
	}

	draw_grid(){
		for(let it of this.s) {
			it.draw();
		}
	}
}

function update_tiles(target, all_tiles) {
	for (let a = 0; a < all_tiles.length; a += 1) {
		if(all_tiles[a].id == target.id) continue;
		for (let i = 0; i < target.seg.length; i += 1) {
			if(target.adj[i] != -1) continue;
			for (let j = 0; j < all_tiles[a].seg.length; j += 1) {
				if(segments_are_close_enough(all_tiles[a].seg[j], target.seg[i])){
					all_tiles[a].adj[j] = target.id;
					target.adj[i] = all_tiles[a].id;
					break;
				}
			}
		}
	}
}

class tile {
	constructor(id, n_sides, x, y, adj, ang = 0) {
		this.n_sides = n_sides;
		this.id = id;
		this.x = x;
		this.y = y;
		this.out_of_bounds = 0;
		this.parent = [x, y];
		this.parent_id = -1;
		this.c = 0;
		this.r = get_r(n_sides);
		this.ap = get_apothem(n_sides);
		this.vert = polygonArr(this.r, n_sides, ang);
		this.vert = this.vert.map((i) => [i[0]+x, i[1]+y]);
		this.seg = get_segments_from_points(this.vert);
		if(adj === 0){
			this.adj = new Array(n_sides).fill(-1);
		}else{
			this.adj = adj;
		}
		this.ang = ang;
	}

	draw(){
		if(g.front.includes(this)){
			fill(col[3 % col.length]);
		}else{
			if(this.out_of_bounds == 1){
				fill(col[4 % col.length]);
			}else{
				fill(col[(this.c + 1) % col.length]);
			}
		}

		stroke(col[4 % col.length]);
		strokeWeight(stroke_weight);
		if(show_tiles){
			beginShape();
			for (let a = 0; a < this.vert.length; a += 1) vertex(...this.vert[a]);
			endShape(CLOSE);
		}
		if(show_tree){
			stroke(col[5 % col.length]);
			line(...this.parent, this.x, this.y);
		}
	}

	get_new_tile(n_seg_expand, new_sides){
		let new_id = last_id;
		last_id += 1;
		this.adj[n_seg_expand] = new_id;
		let new_ap = get_apothem(new_sides);
		let new_vx = ((this.seg[n_seg_expand][0][0] + this.seg[n_seg_expand][1][0])/2 - this.x);
		let new_vy = ((this.seg[n_seg_expand][0][1] + this.seg[n_seg_expand][1][1])/2 - this.y);
		let dd = sqrt(new_vx**2 + new_vy**2);
		new_vx = (this.ap+new_ap)*new_vx/dd + this.x;
		new_vy = (this.ap+new_ap)*new_vy/dd + this.y;
		let new_start_ang = atan2(this.seg[n_seg_expand][1][1]-new_vy, this.seg[n_seg_expand][1][0]-new_vx);
		let new_contact = 0;
		let new_adj = new Array(new_sides).fill(-1);
		new_adj[new_contact] = this.id;
		let nt = new tile(new_id, new_sides, new_vx, new_vy, new_adj, new_start_ang);
		nt.parent = [this.x, this.y];
		nt.parent_id = this.id;
		return nt;
	}
}

